(772416, 84824, 21034, '<td valign="top">I love the idea, but would''ve preferred this w/o the glare on the left side and that trace of a shadow on the right.</td>', 'I love the idea, but would''ve preferred this w/o the glare on the left side and that trace of a shadow on the right.', '2004-06-21 22:09:42.000000', NULL, 1),
(772420, 84834, 21034, '<td valign="top">The composition really grabbed me, and the yellow sets the hook. Very nice.</td>', 'The composition really grabbed me, and the yellow sets the hook. Very nice.', '2004-06-21 22:11:43.000000', NULL, 1),
(772421, 84634, 11518, '<td valign="top">Nice idea...not sure whether I would have included everyone.  Focussing on one musician might have produced a stronger impact.</td>', 'Nice idea...not sure whether I would have included everyone.  Focussing on one musician might have produced a stronger impact.', '2004-06-21 22:13:32.000000', NULL, 1),
(772422, 84930, 21034, '<td valign="top">Awesome idea! I would have killed the glare on the right side of the glass, though.</td>', 'Awesome idea! I would have killed the glare on the right side of the glass, though.', '2004-06-21 22:13:50.000000', NULL, 1),
